      ACCEPT_TOKEN(anon_sym_RETURN);
      END_STATE();
    case 122:
      ACCEPT_TOKEN(anon_sym_POINTER);
      END_STATE();
    case 123:
      if (lookahead == 'R') ADVANCE(124);
